{"hypotheses": [
  {
    "name": "Analyst Revision–Profitability Synergy",
    "mechanism": "Analyst earnings forecast revisions capture timely information while profitability factors represent fundamental strength. Their combination exploits both forward-looking analyst insights and stable business quality. This synergy may compound return predictability, as analysts are more effective when fundamentals support their optimism or pessimism, yielding excess returns versus each alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": 1.0, "primitive": "OperProf"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Volatility-Resistant Quality-Momentum",
    "mechanism": "In periods of high market volatility, quality and momentum signals can become more distinct as risk-averse and risk-seeking investors react differently. A composite that is long quality (OperProfRD) and momentum (Mom12m), but only when VIX is above its trailing median, should capture volatility-driven mispricings.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProfRD"},
        {"weight": 1.0, "primitive": "Mom12m"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Value-Momentum Volatility Switch",
    "mechanism": "Momentum and value signals often cyclically offset each other’s drawdowns. By going long value (BM) and short momentum (Mom12m) only when market volatility is below median, the composite aims to exploit the regime-dependent risk appetite of investors, increasing the risk-adjusted premium.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": -1.0, "primitive": "Mom12m"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "small", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Asset Growth–Short Interest Contrarian",
    "mechanism": "Firms with high asset growth and high short interest tend to underperform due to overinvestment and informed negative sentiment. Shorting both via a composite should amplify the negative return premium as it combines fundamental and sentiment-based mispricing.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": -1.0, "primitive": "ShortInterest"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "ShortInterest", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Leverage–Low Volatility Defensive",
    "mechanism": "Stocks with low leverage and low realized volatility are less susceptible to distress risk and market shocks, especially when the yield curve is positive, making them more attractive defensively. Combining these should enhance downside protection beyond either alone.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "Leverage"},
        {"weight": -1.0, "primitive": "RealizedVol"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 40
  },
  {
    "name": "Earnings Surprise–Illiquidity Premium",
    "mechanism": "Positive earnings surprises in illiquid stocks are slow to be reflected in prices due to trading frictions. A composite that is long both earnings surprise and illiquidity signals should capture delayed price reactions, yielding a premium not present in liquid stocks or in either factor separately.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 1.0, "primitive": "Illiquidity"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Organizational Capital–Long-Term Reversal",
    "mechanism": "Firms with high organizational capital but poor past long-term returns are subject to underappreciated recovery opportunities. Combining organizational capital (OrgCap) with long-term reversal (LRreversal) captures both persistent intangible value and mean-reverting mispricing.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 1.0, "primitive": "LRreversal"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "Share Repurchase–Low Accruals Compounder",
    "mechanism": "Firms repurchasing shares and with low accruals tend to have disciplined capital allocation and high earnings quality. The composite exploits the persistent undervaluation from high-quality capital return and cash earnings, creating a premium distinct from either factor alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": -1.0, "primitive": "Accruals"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 36
  }
]}
